    # Deterministic Clarke-gradient sampling polish.  The affine normalization
    # removes translation, rotation, and scale before probing nonsmooth
    # bottleneck exchanges; only strictly feasible score improvements survive.
    def _clarke_sample_polish(candidate):
        """Perform bounded active-facet sampling with deterministic backtracking."""
        current = np.asarray(candidate, dtype=float).copy()
        rng_local = np.random.default_rng(13013)

        def valid(p):
            try:
                h = ConvexHull(p)
                if h.volume <= 1e-12:
                    return False
                q = p[h.vertices]
                edge = np.roll(q, -1, axis=0) - q
                turn = np.roll(edge, -1, axis=0)
                if np.min(edge[:, 0] * turn[:, 1]
                          - edge[:, 1] * turn[:, 0]) <= 1e-10:
                    return False
                inside = (
                    edge[:, None, 0] * (p[None, :, 1] - q[:, None, 1])
                    - edge[:, None, 1] * (p[None, :, 0] - q[:, None, 0])
                )
                return bool(np.min(inside) >= -1e-9)
            except Exception:
                return False

        def normalized_areas(p):
            try:
                h = ConvexHull(p)
                return 0.5 * np.abs(dets(p)) / max(float(h.volume), 1e-12)
            except Exception:
                return np.full(len(triples), -np.inf)

        # The incumbent plus nine deterministic tangent probes are the local
        # starts requested by the active-facet sampling strategy.
        starts = [current.copy()]
        for radius, axis in (
            (2e-5, 0), (2e-5, 1), (2e-5, 2),
            (7e-5, 0), (7e-5, 1), (7e-5, 2),
            (4e-5, 3), (9e-5, 4), (6e-5, 5)
        ):
            direction = rng_local.normal(size=current.shape)
            direction -= direction.mean(axis=0, keepdims=True)
            norm = np.linalg.norm(direction)
            if norm > 0.0:
                direction *= radius / norm
            probe = np.clip(current + direction, 0.0, 1.0)
            starts.append(probe if valid(probe) else current.copy())

        for start in starts:
            incumbent = start.copy()
            incumbent_value = score(incumbent)

            for _ in range(28):
                areas = normalized_areas(incumbent)
                if not np.all(np.isfinite(areas)):
                    break
                minimum = float(np.min(areas))
                active = np.flatnonzero(areas <= 1.08 * minimum + 1e-12)
                if len(active) == 0:
                    break

                # Sample the local Clarke cone using symmetric tangent
                # perturbations and retain directions improving every active
                # facet in aggregate.
                directions = []
                for radius in (2e-5, 7e-5):
                    for sample in range(8):
                        d = rng_local.normal(size=incumbent.shape)
                        d -= d.mean(axis=0, keepdims=True)
                        d -= np.mean(d * (incumbent - 0.5)) / (
                            np.sum((incumbent - 0.5) ** 2) + 1e-15
                        ) * (incumbent - 0.5)
                        dn = np.linalg.norm(d)
                        if dn > 1e-14:
                            directions.append(d * (radius / dn))
                            directions.append(-d * (radius / dn))

                accepted = False
                for direction in directions:
                    trial = incumbent + direction
                    if not valid(trial):
                        continue
                    trial_value = score(trial)
                    if trial_value <= incumbent_value + 1e-12:
                        continue

                    # Backtrack while preserving the same hull chamber and
                    # requiring strict improvement of the complete objective.
                    step = 1.0
                    for _ in range(8):
                        candidate_trial = incumbent + step * direction
                        if valid(candidate_trial):
                            value = score(candidate_trial)
                            if value > incumbent_value + 1e-12:
                                incumbent = candidate_trial
                                incumbent_value = value
                                accepted = True
                                break
                        step *= 0.5
                    if accepted:
                        break

                if not accepted:
                    break

            if incumbent_value > score(current):
                current = incumbent

        return current

    best = _clarke_sample_polish(best)
    return np.asarray(np.clip(best, 0.0, 1.0), dtype=float)
